package com.example.mementowidgets;
import android.app.Activity;import android.app.DatePickerDialog;import android.app.AlertDialog;import android.os.Bundle;import android.graphics.Color;import android.view.View;import android.widget.*;import java.time.LocalDate;import java.util.List;
public class MainActivity extends Activity {
 LinearLayout root,quoteList; TextView birthLabel,lifeLabel;
 int dp(float v){return (int)(getResources().getDisplayMetrics().density*v+.5f);}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(35,39,47));t.setPadding(0,dp(8),0,dp(8));return t;}
 Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->action.run());return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(18),dp(20),dp(24));root.setBackgroundColor(Color.rgb(248,248,250));ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);TextView title=text("Memento Widgets",27);title.setTypeface(null,1);root.addView(title);root.addView(text("Two independent home-screen widgets. Add them from your launcher's Widgets menu.",14));root.addView(text("LIFE PROGRESS",19));birthLabel=text("",16);root.addView(birthLabel);root.addView(button("Choose date of birth",()->{LocalDate d=Store.dob(this);new DatePickerDialog(this,(picker,y,m,day)->{Store.prefs(this).edit().putString("dob",LocalDate.of(y,m+1,day).toString()).apply();updateLife();},d.getYear(),d.getMonthValue()-1,d.getDayOfMonth()).show();}));lifeLabel=text("",16);root.addView(lifeLabel);SeekBar lifespan=new SeekBar(this);lifespan.setMax(100);lifespan.setProgress(Store.lifespan(this)-20);root.addView(lifespan);lifespan.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int v,boolean from){lifeLabel.setText("Assumed lifespan: "+(v+20)+" years");if(from){Store.prefs(MainActivity.this).edit().putInt("lifespan",v+20).apply();LifeWidget.refresh(MainActivity.this);}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});root.addView(text("* A reflective estimate, not a prediction of life expectancy.",12));root.addView(text("MY QUOTES",19));root.addView(button("+ Add quote",()->editQuote(-1)));quoteList=new LinearLayout(this);quoteList.setOrientation(1);root.addView(quoteList);updateLife();refreshQuotes();}
 void updateLife(){birthLabel.setText("Date of birth: "+Store.dob(this));lifeLabel.setText("Assumed lifespan: "+Store.lifespan(this)+" years");LifeWidget.refresh(this);}
 void refreshQuotes(){quoteList.removeAllViews();List<String> qs=Store.quotes(this);for(int i=0;i<qs.size();i++){final int index=i;LinearLayout row=new LinearLayout(this);row.setOrientation(1);row.setPadding(0,dp(9),0,dp(9));row.addView(text((i+1)+". "+qs.get(i),15));LinearLayout actions=new LinearLayout(this);actions.setOrientation(0);actions.addView(button("Edit",()->editQuote(index)));actions.addView(button("Delete",()->new AlertDialog.Builder(this).setTitle("Delete quote?").setPositiveButton("Delete",(d,w)->{List<String> q=Store.quotes(this);q.remove(index);Store.saveQuotes(this,q);refreshQuotes();QuoteWidget.refresh(this);}).setNegativeButton("Cancel",null).show()));row.addView(actions);quoteList.addView(row);} }
 void editQuote(int index){List<String> qs=Store.quotes(this);EditText input=new EditText(this);input.setSingleLine(false);input.setMinLines(3);input.setPadding(dp(18),dp(8),dp(18),dp(8));if(index>=0)input.setText(qs.get(index));new AlertDialog.Builder(this).setTitle(index<0?"Add quote":"Edit quote").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String value=input.getText().toString().trim();if(value.isEmpty())return;List<String> list=Store.quotes(this);if(index<0)list.add(value);else list.set(index,value);Store.saveQuotes(this,list);refreshQuotes();QuoteWidget.refresh(this);}).show();}
}
